function drawScene(){const canvas=$('scene'),rect=canvas.getBoundingClientRect(),dpr=Math.min(2,devicePixelRatio||1);canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);const ctx=canvas.getContext('2d');ctx.fillStyle='#ead5ac';ctx.fillRect(0,0,canvas.width,canvas.height);if(background.complete&&background.naturalWidth){const scale=Math.max(canvas.width/background.width,canvas.height/background.height),w=background.width*scale,h=background.height*scale;ctx.drawImage(background,(canvas.width-w)/2,(canvas.height-h)/2,w,h);const rabbit=$('rabbit-postman'),baseline=((canvas.height-h)/2+h*.515)/dpr,size=Math.max(80,Math.min(w*.252/dpr,baseline-60));rabbit.style.width=size+'px';rabbit.style.height=size+'px';rabbit.style.left=((canvas.width-w)/2+w*.5)/dpr-size/2+'px';rabbit.style.top=baseline-size+'px';}}
new ResizeObserver(drawScene).observe($('scene'));
function artFor(name){const picture=window.PostVocabulary.items.find(item=>item.name===name);if(picture)return picture.svg;const word=words.find(x=>x.name===name)||letterVocabulary.find(x=>x.name===name);if(extraArt[name])return `<span class="picture-emoji" aria-hidden="true">${extraArt[name]}</span>`;return window.shopWordArt(word);}
function parcelMarkup(){return `<img class="parcel-art" src="assets/parcel.webp" alt=""><span class="parcel-label"><span class="parcel-picture">${artFor(state.parcel.name)}</span></span>`;}
function pool(){return state.stage===2?[...saved.words]:[...saved.letters];}
function parcelPool(){return state.stage===2?words.filter(x=>saved.words.includes(x.name)):letterVocabulary.filter(x=>saved.letters.includes(x.letter));}
function nextParcel(){if(!state.deck.length){state.deck=shuffled(parcelPool());if(state.deck.length>1&&state.deck.at(-1).name===state.last)[state.deck[0],state.deck[state.deck.length-1]]=[state.deck.at(-1),state.deck[0]];}const result=state.deck.pop();state.last=result.name;return result;}
function prompt(){const item=state.parcel;if(!item)return 'Welcome to the parcel counter!';return state.stage===2?`${item.name}. Can you find the word on a bin?`:`${item.name}. Which letter does the word ${item.name} start with?`;}
function start(stage=state.stage){cancelDrag();cancelSpeech();if($('complete').open)$('complete').close();state.stage=stage;state.session++;state.delivered=0;state.deck=[];state.last='';$('welcome').hidden=true;question();}
function question(){cancelDrag();$('delivery').classList.remove('fly');$('delivery').replaceChildren();state.phase='arriving';state.praisePending=false;state.timer=0;state.hints=0;state.selected=false;state.turn++;state.parcel=nextParcel();state.customerIndex=(state.turn-1)%customers.length;state.target=state.stage===2?state.parcel.name:state.parcel.letter;state.choices=shuffled([state.target,...shuffled(pool().filter(x=>x!==state.target)).slice(0,2)]);
 $('visitor').hidden=false;$('visitor').className='visitor arriving';$('visitor').dataset.animal=state.customerIndex;$('visitor').style.setProperty('--sprite',customers[state.customerIndex].sprite);$('visitor-name').textContent=customers[state.customerIndex].name;
 $('mail').disabled=true;$('mail').classList.remove('selected','posted','picked-up');$('mail-text').innerHTML=parcelMarkup();$('mail-caption').textContent='DRAG ME';$('mail').setAttribute('aria-label',`Package with a picture of ${state.parcel.name}. Drag into the matching bin.`);
 $('task-label').textContent=state.stage===2?'PICTURE → WORD':state.stage===1?'PICTURE → LITTLE LETTER':'PICTURE → BIG LETTER';$('instruction').textContent=state.stage===2?'Drag the picture package to its word.':'Drag the package to its first-letter bin.';$('feedback').textContent='A customer is coming to the counter.';$('speech').textContent=`Here comes ${customers[state.customerIndex].name}!`;
 $('mailboxes').innerHTML=state.choices.map((value,i)=>`<button disabled class="mailbox ${state.stage===2?'word-bin':''}" data-answer="${value}" aria-label="Delivery bin ${state.stage===1?value.toLowerCase():value}"><span class="slot"></span><span class="label">${state.stage===1?value.toLowerCase():state.stage===2?value.toUpperCase():value}</span><span class="key">${i+1}</span></button>`).join('');$('hint').disabled=true;$('listen').disabled=true;chrome();}
function customerReady(){state.phase='ready';state.timer=0;$('visitor').classList.remove('arriving');$('mail').disabled=false;[...$('mailboxes').children].forEach(b=>b.disabled=false);$('hint').disabled=false;$('listen').disabled=false;$('feedback').textContent='Look at the picture. Drag the package into a bin.';$('speech').textContent=`Please send my ${state.parcel.name} package!`;say(prompt());}
function submit(value,origin=null){if(state.phase!=='ready')return;const chosen=[...$('mailboxes').children].find(x=>x.dataset.answer===value);if(!chosen)return;state.dropOrigin=origin;cancelDrag();[...$('mailboxes').children].forEach(b=>b.disabled=true);$('mail').disabled=true;$('hint').disabled=true;state.timer=0;
 if(value!==state.target){state.phase='retry';chosen.classList.add('wrong');$('feedback').textContent='Good try! Take another look.';$('speech').textContent='You can do it. Let’s try again!';say('Good try. Look at the picture and try again. You can do it!');return;}
 state.phase='delivering';state.delivered++;saved.stamps++;persist();chosen.classList.add('correct');$('delivery').innerHTML=parcelMarkup();$('visitor').classList.add('empty-handed');const sceneRect=document.querySelector('.post-office').getBoundingClientRect(),binRect=chosen.getBoundingClientRect(),mailRect=state.dropOrigin||$('mail').getBoundingClientRect();$('delivery').style.left=(mailRect.x+mailRect.width/2-sceneRect.x)+'px';$('delivery').style.top=(mailRect.y+mailRect.height/2-sceneRect.y)+'px';$('delivery').style.setProperty('--dx',(binRect.x+binRect.width/2-mailRect.x-mailRect.width/2)+'px');$('delivery').style.setProperty('--dy',(binRect.y+binRect.height*.3-mailRect.y-mailRect.height/2)+'px');$('mail').classList.add('posted');$('delivery').classList.remove('fly');void $('delivery').offsetWidth;$('delivery').classList.add('fly');$('feedback').textContent='Delivered! One happy forest friend. ★';const praise=window.nextPostPraise();$('speech').textContent=praise;chrome();chime();sayPraise(praise);}
function update(ms){if($('teacher').open)return;window.RabbitPostman?.update(ms,{phase:state.phase,dragging:!!drag,voicePlaying:!!window.PostNaturalVoice?.playing||('speechSynthesis' in window&&speechSynthesis.speaking),gentle:!!saved.gentle});if(!['arriving','retry','delivering','leaving'].includes(state.phase))return;let remaining=Math.max(0,Number(ms)||0);let guard=0;const durations={arriving:1100,retry:1400,delivering:1000,leaving:800};while(remaining>0&&guard++<8&&durations[state.phase]){const elapsed=Math.min(remaining,durations[state.phase]-state.timer);state.timer+=elapsed;remaining-=elapsed;if(state.timer<durations[state.phase])break;if(state.phase==='delivering'&&state.praisePending)break;state.timer=0;
 if(state.phase==='arriving')customerReady();else if(state.phase==='retry'){state.phase='ready';[...$('mailboxes').children].forEach(b=>{b.disabled=false;b.classList.remove('wrong');});$('mail').disabled=false;$('hint').disabled=false;$('feedback').textContent='Same package. Take another look and try again.';}
 else if(state.phase==='delivering'){state.phase='leaving';$('delivery').classList.remove('fly');$('delivery').replaceChildren();$('visitor').className='visitor leaving empty-handed';$('speech').textContent='Thank you! See you next time.';$('feedback').textContent='The customer is leaving. A new friend will arrive soon.';}
 else if(state.phase==='leaving'){if(state.delivered>=8)finish();else question();}
 }}
