function cancelDrag(){if(!drag)return;drag.ghost?.remove();drag=null;$('mail').classList.remove('picked-up');$('visitor').classList.remove('empty-handed');[...$('mailboxes').children].forEach(b=>b.classList.remove('drag-over'));}
function moveDrag(e){if(!drag||drag.id!==e.pointerId||state.phase!=='ready')return;drag.moved ||= Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>8;drag.ghost.style.left=e.clientX+'px';drag.ghost.style.top=e.clientY+'px';const box=document.elementFromPoint(e.clientX,e.clientY)?.closest('.mailbox');[...$('mailboxes').children].forEach(b=>b.classList.toggle('drag-over',b===box));}
$('mail').addEventListener('pointerdown',e=>{if(state.phase!=='ready'||e.button!==0)return;const box=$('mail').getBoundingClientRect(),ghost=document.createElement('div');ghost.className='drag-ghost full-parcel';ghost.innerHTML=parcelMarkup();ghost.style.width=box.width+'px';ghost.style.height=box.height+'px';ghost.style.left=e.clientX+'px';ghost.style.top=e.clientY+'px';document.body.append(ghost);drag={id:e.pointerId,x:e.clientX,y:e.clientY,ghost,moved:false};$('mail').setPointerCapture(e.pointerId);state.selected=true;$('mail').classList.add('selected','picked-up');$('visitor').classList.add('empty-handed');});
$('mail').addEventListener('pointermove',moveDrag);$('mail').addEventListener('pointerup',e=>{if(!drag||drag.id!==e.pointerId)return;const wasDrag=drag.moved,box=document.elementFromPoint(e.clientX,e.clientY)?.closest('.mailbox'),origin=drag.ghost.getBoundingClientRect();cancelDrag();if(wasDrag&&box)submit(box.dataset.answer,origin);});$('mail').addEventListener('pointercancel',cancelDrag);
$('mail').onclick=()=>{if(state.phase==='ready'){state.selected=true;$('mail').classList.add('selected');}};
$('mailboxes').onclick=e=>{const box=e.target.closest('[data-answer]');if(box&&state.selected)submit(box.dataset.answer);else if(box&&state.phase==='ready')$('feedback').textContent='Pick up the picture package first, then choose a bin.';};$('lessons').onclick=e=>{const b=e.target.closest('[data-stage]');if(b&&!b.disabled)start(Number(b.dataset.stage));};$('start').onclick=()=>start();$('continue').onclick=()=>start(Math.min(2,state.stage+1));$('repeat').onclick=()=>start();$('listen').onclick=()=>say(prompt());$('hint').onclick=hint;
$('sound').onclick=()=>{saved.voice=!saved.voice;persist();chrome();if(!saved.voice)cancelSpeech();else if(state.phase==='ready')say(prompt());};
function fullscreen(){if(document.fullscreenElement)document.exitFullscreen?.().catch(()=>{});else document.documentElement.requestFullscreen?.().catch(()=>{});}$('fullscreen').onclick=fullscreen;
function showSettings(){cancelDrag();cancelSpeech();$('letter-set').value=saved.letters;$('practice').checked=saved.practice;$('gentle').checked=saved.gentle;$('word-picker').innerHTML=words.map(x=>`<label class="check"><input type="checkbox" value="${x.name}" ${saved.words.includes(x.name)?'checked':''}>${x.name}</label>`).join('');loadVoices();$('settings-message').textContent='';$('teacher').showModal();}
$('voice-preview').onclick=()=>{const previous=saved.voiceURI;saved.voiceURI=$('voices').value;const wasOn=saved.voice;saved.voice=true;say('Hello, little postie! What a lovely package. Look at the picture, then drag it into the matching bin. Wonderful work!');saved.voiceURI=previous;saved.voice=wasOn;};$('settings').onclick=showSettings;$('close-settings').onclick=()=>$('teacher').close();$('apply').onclick=()=>{const letters=[...new Set($('letter-set').value.toUpperCase().replace(/[^A-Z]/g,''))].join(''),selected=[...$('word-picker').querySelectorAll('input:checked')].map(x=>x.value);if(letters.length<2||selected.length<2){$('settings-message').textContent='Choose at least two different letters and two words.';return;}saved.letters=letters;saved.words=selected;saved.practice=$('practice').checked;saved.gentle=$('gentle').checked;saved.voiceURI=$('voices').value;persist();$('teacher').close();if(!saved.practice&&state.stage>saved.unlocked)state.stage=saved.unlocked;if(state.phase==='welcome')chrome();else start();};
